def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    additions = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Continue the diagonal pair beyond either end, using the vacant end.
                ends = ((r - dr, c - dc), (r2 + dr, c2 + dc))
                free = [(rr, cc) for rr, cc in ends
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg]
                if free:
                    rr, cc = free[-1]
                    additions.append((rr, cc, color))
    for r, c, color in additions:
        out[r][c] = color
    return out
